style.css:
html::before{
		content: "";
    position: fixed;
    transform: translateY(-17px) scaleX(1.0);
    background: linear-gradient(90deg, red, orange, yellow, green, blue, violet);
    filter: blur(10px);
    height: 20px;
    width: calc(100vw + 20px);
    left:-20px;
    pointer-events: none;
    border-radius: 0;
  	z-index:999999;
}
